# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs, factor=10):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: sift
def sift(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(digest(intake(gather(emit(raw)))))

